import {
  collides,
  bounceBall,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('bounceBall: top-face hit flips vy up and pushes ball out', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20 };
  const ball = { x: 110, y: 118, r: 7, vx: 0, vy: 50 }; // coming down onto the top
